import {redirect} from "next/navigation";import {Car,LayoutDashboard,MessageSquare,PlusCircle,Store} from "lucide-react";import {DashboardShell} from "@/components/dashboard/shell";import {requireUser} from "@/lib/auth";import {connectMongoose} from "@/lib/db";import {VendorProfileModel} from "@/models/VendorProfile";export const metadata={robots:{index:false,follow:false}};export default async function Layout({children}:{children:React.ReactNode}){const user=await requireUser("/vendor");if(user.role==="ADMIN")redirect("/admin");await connectMongoose();const profile=await VendorProfileModel.findOne({userId:user.id}).select("status displayName").lean();const links=[{href:"/vendor",label:"Overview",icon:LayoutDashboard},...(profile?.status==="APPROVED"?[{href:"/vendor/cars",label:"Listings",icon:Car},{href:"/vendor/cars/new",label:"Add a car",icon:PlusCircle},{href:"/vendor/inquiries",label:"Buyer inquiries",icon:MessageSquare},{href:"/vendor/profile",label:"Seller profile",icon:Store}]:[{href:"/become-a-vendor",label:profile?"Application status":"Seller setup",icon:Store}])];return <DashboardShell title={profile?.displayName||"Seller workspace"} subtitle="Seller account" links={links}>{children}</DashboardShell>}
